-- patch_suppositions_2026-11-24 -- les controles, rejouables. AUCUNE ECRITURE.
select 'suppositions_2026-11-24' as lot, (select count(*) from public.app_classeur_realignement_journal where lot = 'suppositions_2026-11-24') as au_journal, (select count(*) from public.app_affaire_repartition_mise_de_cote where mise_de_cote_par = 'patch_suppositions_2026-11-24') as mises_de_cote, (select md5(coalesce(string_agg(concat_ws('|', app_chaine_id, cote, rang, hektor_user_id, nom_au_moment, pourcentage, origine, ecrit_par), ';' order by app_chaine_id, cote, rang), '')) from public.app_affaire_repartition where app_chaine_id in (1027, 1875, 4234, 6391, 9370, 27984)) as empreinte, '91a61e04b6d5507cd49c95b4af7d5f89' as attendue;
